-- ═══ M80-2 — Gegenprobe: dieselbe Abfrage OHNE den Katalog-Join ═════════════
-- Das ist genau die Fassung, die L12 am 06.08.2026 mit 4,2 ms gemessen hat.
-- Die Differenz zu M80-1 ist der Preis des Joins und nichts sonst.
SELECT 'M80-2 OHNE KATALOG-JOIN, NEXANS (1 aufwaermen + 3)' AS marke;
SELECT p.ProcessID, p.ProcessName, pr.ProjectName FROM GlassfishDB.Process p JOIN GlassfishDB.ProjectMandant pm ON pm.ProjectID = p.ProjectID LEFT JOIN GlassfishDB.Project pr ON pr.ProjectID = p.ProjectID WHERE pm.MandantID = 'NEXANS' ORDER BY pr.ProjectName, p.ProcessName;
SELECT p.ProcessID, p.ProcessName, pr.ProjectName FROM GlassfishDB.Process p JOIN GlassfishDB.ProjectMandant pm ON pm.ProjectID = p.ProjectID LEFT JOIN GlassfishDB.Project pr ON pr.ProjectID = p.ProjectID WHERE pm.MandantID = 'NEXANS' ORDER BY pr.ProjectName, p.ProcessName;
SELECT p.ProcessID, p.ProcessName, pr.ProjectName FROM GlassfishDB.Process p JOIN GlassfishDB.ProjectMandant pm ON pm.ProjectID = p.ProjectID LEFT JOIN GlassfishDB.Project pr ON pr.ProjectID = p.ProjectID WHERE pm.MandantID = 'NEXANS' ORDER BY pr.ProjectName, p.ProcessName;
SELECT p.ProcessID, p.ProcessName, pr.ProjectName FROM GlassfishDB.Process p JOIN GlassfishDB.ProjectMandant pm ON pm.ProjectID = p.ProjectID LEFT JOIN GlassfishDB.Project pr ON pr.ProjectID = p.ProjectID WHERE pm.MandantID = 'NEXANS' ORDER BY pr.ProjectName, p.ProcessName;

