-- ═══ M80-5 — Das Statement, das Vorschau und Ausfuehrung teilen ═════════════
-- Das Projekt wird hier hergeleitet und nicht eingetragen (G1): das groesste
-- Projekt von VOTG, laut M76 mit 226 Prozessen das groesste des Bestands.
SELECT 'M80-5 groesstes Projekt herleiten' AS marke;
SELECT p.ProjectID INTO @projekt
FROM GlassfishDB.Process p
JOIN GlassfishDB.ProjectMandant pm ON pm.ProjectID = p.ProjectID
WHERE pm.MandantID = 'VOTG'
GROUP BY p.ProjectID
ORDER BY COUNT(*) DESC, p.ProjectID ASC
LIMIT 1;
SELECT COUNT(*) AS prozesse_im_groessten_projekt
FROM GlassfishDB.Process p
JOIN GlassfishDB.ProjectMandant pm ON pm.ProjectID = p.ProjectID
WHERE pm.MandantID = 'VOTG' AND p.ProjectID = @projekt;

SELECT 'M80-5 EXPLAIN Projektbestand' AS marke;
EXPLAIN
select `GlassfishDB`.`Process`.`ProcessID`, `overlord_monitor`.`process_catalog`.`pflegestatus` from `GlassfishDB`.`Process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `GlassfishDB`.`Process`.`ProjectID` left outer join `overlord_monitor`.`process_catalog` on `overlord_monitor`.`process_catalog`.`process_id` = `GlassfishDB`.`Process`.`ProcessID` where (`GlassfishDB`.`ProjectMandant`.`MandantID` = 'VOTG' and `GlassfishDB`.`Process`.`ProjectID` = @projekt);

